harLength\n      }\n    });\n  }\n}\n// Position after existing content in the same source group, without modifying it.\nconst right = Math.max(0, ...input.children.map(node =>\n  (typeof node.position?.x === \"number\" ? node.position.x : 0) +\n  (typeof node.width === \"number\" ? node.width : 420)\n));\nfor (const node of createNodes) node.position.x = right + 80;\nreturn { allowOverwrite: false, createNodes };"}},{"id":"builtin-one-click-v1:write","type":"taskNode","position":{"x":720,"y":0},"data":{"workflowKey":"tapcanvas.builtin.one-click-video-nodes/v1","workflowInstanceId":"tapcanvas.builtin.one-click-video-nodes/v1","workflowDefinitionVersion":1,"workflowPermission":"admin","adminWorkflow":true,"status":"idle","kind":"workflowStage","label":"添加到当前画布","description":"添加到当前画布","workflowNodeId":"write","workflowNodeKind":"tool_invocation","workflowAtomicSpec":{"version":1,"category":"tool","operation":"tool_invocation","executorRef":"agents.tool.invoke/v1","executionMode":"once","inputPorts":["arguments"],"outputPorts":["result"]},"workflowInputPorts":["arguments"],"workflowOutputPorts":["result"],"workflowOutputArtifactType":"workflow.tool-result/v1","workflowToolInvocationName":"tapcanvas_flow_patch","workflowToolId":"tapcanvas_flow_patch"}},{"id":"builtin-one-click-v1:output","type":"taskNode","position":{"x":960,"y":0},"data":{"workflowKey":"tapcanvas.builtin.one-click-video-nodes/v1","workflowInstanceId":"tapcanvas.builtin.one-click-video-nodes/v1","workflowDefinitionVersion":1,"workflowPermission":"admin","adminWorkflow":true,"status":"idle","kind":"workflowOutput","label":"视频节点交付记录","description":"视频节点交付记录","workflowNodeId":"output","workflowNodeKind":"output","workflowAtomicSpec":{"version":1,"category":"control","operation":"output","executorRef":"workflow.output/v1","executionMode":"once","inputPorts":["input"],"outputPorts":["output"]},"workflowInputPorts":["input"],"workflowOutputPorts":["output"]}}],"edges":[{"id":"builtin-one-click-v1:trigger:sou